-- Bounded current evidence; does not parse raw content or modify state.
BEGIN READ ONLY;SET LOCAL statement_timeout='10s';
SELECT jsonb_build_object('observed_at',clock_timestamp(),
 'tasks',(SELECT jsonb_agg(jsonb_build_object('task_id',task_id,'stage',stage,'status',status,'executions',executions,'checkpoint',checkpoint,'not_before',not_before,'blocker_code',blocker_code,'last_failure_class',last_failure_class) ORDER BY created_at,task_id) FROM population_top3000_202608_202609_v1.pipeline_task WHERE family_id='P01' AND payload->>'kind'='MASSIVE_MINUTE_PILOT_V1'),
 'source_pages',(SELECT jsonb_agg(jsonb_build_object('archive_key',archive_key,'page',page_number,'source_id',source_id,'sha256',source_sha256,'wire_sha256',wire_sha256,'stored_bytes',response_bytes,'wire_bytes',wire_bytes,'source_records',result_count,'results_presence',results_presence,'request_url',request_url,'next_url',next_url,'retrieved_at',retrieved_at,'normalized',normalized_rows,'normalized_at',normalized_at,'verified',verified_rows,'verified_at',verified_at,'source_summary',source_summary) ORDER BY archive_key,page_number) FROM population_top3000_202608_202609_v1.massive_minute_page_v1),
 'typed_counts',(SELECT jsonb_build_object('occurrences',count(*),'usable_timestamp_rows',count(*) FILTER(WHERE timestamp_in_requested_window),'required_fields_structurally_usable_rows',count(*) FILTER(WHERE required_bar_fields_structurally_usable),'explicit_zero_volume',count(*) FILTER(WHERE share_volume=0),'missing_volume',count(*) FILTER(WHERE (missing_mask&32)<>0),'out_of_window',count(*) FILTER(WHERE (structure_mask&2)<>0),'unaligned_timestamp',count(*) FILTER(WHERE (structure_mask&4)<>0),'min_valid_bar_start',min(bar_start_at) FILTER(WHERE timestamp_in_requested_window),'max_valid_bar_start',max(bar_start_at) FILTER(WHERE timestamp_in_requested_window),'publications',count(*) FILTER(WHERE publication_eligible),'sip_verified',count(*) FILTER(WHERE sip_feed_verified)) FROM population_top3000_202608_202609_v1.massive_minute_provisional_v1),
 'table_bytes',(SELECT jsonb_object_agg(c.relname,pg_total_relation_size(c.oid)) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='population_top3000_202608_202609_v1' AND c.relname IN('massive_minute_page_v1','massive_minute_bar_v1','massive_minute_batch_v1')),
 'recent_attempts',(SELECT jsonb_agg(to_jsonb(x) ORDER BY started_at DESC) FROM (SELECT a.started_at,a.ended_at,a.outcome,t.stage,extract(epoch FROM a.ended_at-a.started_at) AS elapsed_seconds FROM population_top3000_202608_202609_v1.pipeline_attempt a JOIN population_top3000_202608_202609_v1.pipeline_task t USING(task_id) WHERE t.family_id='P01' AND t.payload->>'kind'='MASSIVE_MINUTE_PILOT_V1' ORDER BY a.started_at DESC LIMIT 20) x),
 'denominator',(SELECT to_jsonb(p) FROM population_top3000_202608_202609_v1.pipeline_partition p WHERE family_id='P01' AND partition_key='massive-minute-AAPL-20260908-v1'),
 'original_alpaca_code_sha256',population_top3000_202608_202609_v1.alpaca_sip_code_hash_v1(),
 'company_population_verified',false,'provider_accuracy_verified',false,'next_action','REVIEW_ONE_RETAINED_PAGE_ENTITLEMENT_BYTES_RUNTIME_RECORDS_AND_TERMINAL_CURSOR_BEFORE_EXPANSION') AS minute_pilot_readback;
COMMIT;
